  fsm.machine @M(%in: i1) -> (i1) attributes {initialState = \"A\"} {
    fsm.state @A output {
      %t = hw.constant 7 : i32
      fsm.output %in : i1
    }
    fsm.state @B output {
      %u = hw.constant 9 : i32
      fsm.output %in : i1
    }
  }
}'''
